use rig::completion::CompletionRequest;
use rig::providers::openai::{self, OpenAI};


let model = OpenAI::from_env()?.completion(openai::GPT_5_5);


let request = CompletionRequest::new("What is the Rust programming language?")
    .preamble("You are a helpful assistant.")
    .temperature(0.7)
    .max_tokens(1000);


let response = model.call(request).await?;
println!("{}", response.text());

let mut history = vec![
    Message::user("My name is Ferris."),
    Message::assistant("Nice to meet you, Ferris!"),
];


let prompt = Message::user("What's my name?");
let response = model
    .call(CompletionRequest::new(prompt.clone()).messages(history.clone()))
    .await?;


history.push(prompt);
history.extend(response.message());

use rig::completion::{CacheRetention, CompletionRequest, Effort, ServiceTier};


let request = CompletionRequest::new("Plan the refactor of the parser module.")
    .reasoning(Effort::High)
    .cache(CacheRetention::Long)
    .service_tier(ServiceTier::Flex)
    .seed(7);


let response = model.call(request).await?;
println!("{}", response.reasoning());

use rig::providers::anthropic::{self, Anthropic};
use rig::providers::anthropic::extension::{AnthropicExt, AnthropicOptions};


let model = Anthropic::from_env()?.completion(anthropic::CLAUDE_SONNET_5_5);


let request = CompletionRequest::new("Name three Rust web frameworks.")
    .provider_option(AnthropicOptions::default().top_k(40));


let response = model.call(request).await?;
let extras = response.extras_lossy::<AnthropicExt>();
println!("stop reason: {:?}, tier: {:?}", extras.stop_reason, extras.service_tier);

let response = model.call(CompletionRequest::new("Write a long poem.").max_tokens(50)).await?;


match response.finish_reason() {
    Some(FinishReason::Length) => println!("cut off: raise max_tokens"),
    Some(FinishReason::ContentFilter) => println!("filtered by the provider"),
    Some(FinishReason::Other(raw)) => println!("provider said: {raw}"),
    _ => println!("{}", response.text()),
}

let response = model.call(CompletionRequest::new("Hi")).await?;
let usage = &response.usage;


println!(
    "in: {}, out: {}, cached: {:?}",
    usage.input_tokens.unwrap_or(0),
    usage.output_tokens.unwrap_or(0),
    usage.cached_input_tokens,
);

use futures::StreamExt;
use rig::completion::CompletionRequest;
use rig::streaming::{Item, StreamEvent};


let mut stream = model.stream(CompletionRequest::new("Tell me a short story."))?;


while let Some(item) = stream.next().await {
    if let Item::Event(StreamEvent::Text { text, .. }) = item? {
        print!("{text}");
    }
}

use rig::completion::{CompletionRequest, CompletionResponse};
use rig::operation::Completion;


async fn summarize(model: &DynModel<Completion>, text: &str) -> Result<String, ProviderError> {
    let request = CompletionRequest::new(format!("Summarize:\n\n{text}"));
    let response: CompletionResponse = model.call(request).await?;
    Ok(response.text())
}
